package hms.core.m1.rsc.rscservice.cache

import com.github.benmanes.caffeine.cache.Cache
import hms.core.m1.rsc.rscservice.cache.repository.CacheRepository
import hms.core.m1.rsc.rscservice.error.CommonError
import hms.core.m1.rsc.rscservice.error.InternalErrorException
import io.micrometer.core.instrument.MeterRegistry
import org.slf4j.LoggerFactory
import org.springframework.beans.factory.annotation.Value
import org.springframework.dao.DataAccessException
import org.springframework.stereotype.Component
import kotlin.Exception

/**
 * Hybrid cache manager using two-tier architecture:
 * - L1: Caffeine (in-memory, per-instance, fast)
 * - L2: MariaDB (shared, distributed, persistent)
 * 
 * Provides near-real-time cross-instance consistency via invalidation polling
 * and eventual consistency via periodic sync scheduler (2-minute default).
 */
@Component
class DistributedMsisdnCacheManager(
    private val cacheRepository: CacheRepository,
    private val caffeineCache: Cache<String, CachedData>,
    private val meterRegistry: MeterRegistry,
    @Value("\${spring.application.name}") val nodeId: String,
    @Value("\${service-api.msisdn-status-cache.neighbouring-countries-vlrAddress}") val msisdnRegexList: List<String>,
    @Value("\${service-api.msisdn-status-cache.neighbouring-countries-cache-invalid-time-minutes}") val neighbouringCacheInvalidTimeMinutes: Long,
    @Value("\${service-api.msisdn-status-cache.non-neighbouring-countries-cache-invalid-time-minutes}") val nonNeighbouringCacheInvalidTimeMinutes: Long) {

    companion object {
        private val LOGGER = LoggerFactory.getLogger(DistributedMsisdnCacheManager::class.java)
    }

    /**
     * Add entry to hybrid cache (L1 + L2)
     * 
     * Write path:
     * 1. Check if already in L1 cache
     * 2. Write to L2 (MariaDB) with TTL
     * 3. Update L1 (Caffeine) cache
     * 4. Trigger invalidation event for other instances
     * 
     * Graceful degradation: If L2 write fails, still updates L1 (degraded mode)
     */
    fun addToCache(msisdn: String, cacheData: CachedData) {
        if (!inCache(msisdn)) {
            LOGGER.info("Msisdn : [$msisdn] not in cache, adding data [$cacheData]")
            val startTime = System.nanoTime()

            try {
                val timeout = getTimeout(cacheData.vlrAddress)

                // Write to L2 (MariaDB) - triggers invalidation log via DB trigger
                cacheRepository.upsert(msisdn, cacheData, timeout)

                // Update L1 (Caffeine)
                caffeineCache.put(msisdn, cacheData)

                val duration = System.nanoTime() - startTime
                LOGGER.debug(
                    "Added to cache msisdn: [{}], data: [{}], duration: [{}ms], node: [{}]",
                    msisdn,
                    cacheData,
                    duration / 1_000_000,
                    nodeId
                )

                // Record metrics
                meterRegistry.counter("cache.write", "status", "success", "node", nodeId).increment()
                meterRegistry.timer("cache.write.duration", "node", nodeId).record(duration, java.util.concurrent.TimeUnit.NANOSECONDS)

            } catch (e: DataAccessException) {
                // MariaDB write failed - degraded mode (L1 only)
                LOGGER.error(
                    "L2 (MariaDB) write failed for [$msisdn], falling back to L1-only mode", e
                )

                // Still update L1 cache for temporary availability
                caffeineCache.put(msisdn, cacheData)

                // Record failure metrics
                meterRegistry.counter("cache.write", "status", "l2_failure", "node", nodeId).increment()

            } catch (e: Exception) {
                LOGGER.error("Error occurred while adding to cache for [$msisdn]", e)
                meterRegistry.counter("cache.write", "status", "error", "node", nodeId).increment()
            }
        } else {
            LOGGER.debug("Msisdn : [$msisdn] already in cache")
            meterRegistry.counter("cache.write", "status", "already_exists", "node", nodeId).increment()
        }
    }

    /**
     * Retrieve from hybrid cache with L1 → L2 fallback
     * 
     * Read path:
     * 1. Check L1 (Caffeine) - if hit, return immediately (~100ns)
     * 2. On L1 miss, check L2 (MariaDB) (~2-5ms)
     * 3. If L2 hit, update L1 and return
     * 4. If both miss, return null
     */
    fun getFromCache(msisdn: String): CachedData? {
        val startTime = System.nanoTime()

        // Check L1 (Caffeine) first
        var cachedData = caffeineCache.getIfPresent(msisdn)

        if (cachedData != null) {
            val duration = System.nanoTime() - startTime
            LOGGER.debug("L1 cache hit for [$msisdn], duration: [${duration / 1_000}µs]")
            meterRegistry.counter("cache.read", "layer", "l1", "result", "hit", "node", nodeId).increment()
            return cachedData
        }

        // L1 miss, check L2 (MariaDB)
        LOGGER.debug("L1 cache miss for [$msisdn], checking L2")
        meterRegistry.counter("cache.read", "layer", "l1", "result", "miss", "node", nodeId).increment()

        try {
            cachedData = cacheRepository.get(msisdn)

            if (cachedData != null) {
                val duration = System.nanoTime() - startTime
                LOGGER.info(
                    "L2 cache hit for [$msisdn], updating L1, " +
                    "duration: [${duration / 1_000_000}ms], data: [$cachedData]"
                )

                // Update L1 cache for future hits
                caffeineCache.put(msisdn, cachedData)

                meterRegistry.counter("cache.read", "layer", "l2", "result", "hit", "node", nodeId).increment()
                meterRegistry.timer("cache.read.l2.duration", "node", nodeId)
                    .record(duration, java.util.concurrent.TimeUnit.NANOSECONDS)
            } else {
                LOGGER.debug("Cache miss (L1 + L2) for [$msisdn]")
                meterRegistry.counter("cache.read", "layer", "l2", "result", "miss", "node", nodeId).increment()
            }

            return cachedData

        } catch (e: DataAccessException) {
            LOGGER.error("L2 (MariaDB) read failed for [$msisdn], returning null", e)
            meterRegistry.counter("cache.read", "layer", "l2", "result", "error", "node", nodeId).increment()
            return null
        }
    }

    /**
     * Remove entry from hybrid cache (L1 + L2)
     * 
     * Removal path:
     * 1. Delete from L2 (MariaDB) - triggers invalidation event
     * 2. Invalidate L1 (Caffeine)
     * 3. Return deleted data
     */
    fun removeFromCache(msisdn: String): CachedData? {
        try {
            LOGGER.info("Removing msisdn [$msisdn] from cache")

            // Remove from L2 (MariaDB) - triggers invalidation via DB trigger
            val removed = cacheRepository.delete(msisdn)

            // Invalidate L1 (Caffeine)
            caffeineCache.invalidate(msisdn)

            if (removed != null) {
                LOGGER.info("Removed [$msisdn] from cache, data: [$removed]")
                meterRegistry.counter("cache.delete", "result", "found", "node", nodeId).increment()
            } else {
                LOGGER.debug("Msisdn [$msisdn] not found in cache for removal")
                meterRegistry.counter("cache.delete", "result", "not_found", "node", nodeId).increment()
            }

            return removed

        } catch (e: DataAccessException) {
            LOGGER.error("Error occurred while trying to remove [$msisdn] from L2 cache", e)
            meterRegistry.counter("cache.delete", "result", "error", "node", nodeId).increment()
            throw InternalErrorException(CommonError(e.message))
        } catch (e: Exception) {
            LOGGER.error("Unexpected error removing [$msisdn] from cache", e)
            meterRegistry.counter("cache.delete", "result", "error", "node", nodeId).increment()
            throw InternalErrorException(CommonError(e.message))
        }
    }

    /**
     * Clear entire cache (L1 + L2)
     * 
     * Note: Eventual consistency - other instances will sync within 2 minutes
     * or 5 seconds if invalidation polling is enabled
     */
    fun removeAllFromCache() {
        LOGGER.info("Clearing entire cache")

        try {
            // Clear L2 (MariaDB) - triggers mass invalidation events
            val deletedCount = cacheRepository.deleteAll()

            // Clear L1 (Caffeine)
            caffeineCache.invalidateAll()

            LOGGER.info("Cleared entire cache: [$deletedCount] entries deleted")
            meterRegistry.counter("cache.clear", "node", nodeId).increment()
            meterRegistry.gauge("cache.clear.entries", listOf(), deletedCount)

        } catch (e: Exception) {
            LOGGER.error("Error clearing cache", e)
            meterRegistry.counter("cache.clear.error", "node", nodeId).increment()
        }
    }

    /**
     * Get cache size (from L1 - approximation)
     * For exact count, use cacheRepository.count() but that's slower
     */
    fun getCacheSize() = caffeineCache.estimatedSize().toInt()

    /**
     * Check if MSISDN is in cache (L1 or L2)
     * Checks L1 first for performance, falls back to L2
     */
    private fun inCache(msisdn: String): Boolean {
        // Check L1 first (fast path)
        if (caffeineCache.getIfPresent(msisdn) != null) {
            return true
        }

        // Fallback to L2 (slower but authoritative)
        return try {
            cacheRepository.get(msisdn) != null
        } catch (e: DataAccessException) {
            LOGGER.error("Error checking L2 cache for [$msisdn]", e)
            false
        }
    }
//    private fun isNeighbouringMsisdn(vlrAddress: String) = msisdnRegexList.map { Regex(it) }.any { regex -> regex.matches(vlrAddress) }

    private fun isNeighbouringMsisdn(vlrAddress: String): Boolean {
        val result = vlrAddress.split(",")
            .map { it.trim() }
            .any { singleVlr ->
                msisdnRegexList.any { Regex(it).matches(singleVlr) }
            }

        LOGGER.debug("VLR check: [{}] → neighbouring=[{}]", vlrAddress, result)

        return result
    }

    private fun getTimeout(vlrAddress: String) = if (isNeighbouringMsisdn(vlrAddress)) neighbouringCacheInvalidTimeMinutes else nonNeighbouringCacheInvalidTimeMinutes
}

