package hms.core.m1.rsc.rscservice.viewer.configuration;

import hms.core.m1.rsc.rscservice.viewer.util.KeycloakUtil;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.convert.converter.Converter;
import org.springframework.security.authentication.AuthenticationManager;
import org.springframework.security.authentication.dao.DaoAuthenticationProvider;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.annotation.web.configurers.AbstractHttpConfigurer;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.core.GrantedAuthority;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.security.core.authority.mapping.GrantedAuthoritiesMapper;
import org.springframework.security.oauth2.core.oidc.user.OidcUserAuthority;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.authentication.SimpleUrlAuthenticationSuccessHandler;
import org.springframework.security.web.header.writers.frameoptions.XFrameOptionsHeaderWriter;
import org.springframework.security.web.util.matcher.AntPathRequestMatcher;

import java.util.*;
import java.util.stream.Collectors;

// no static imports

/*
 * (C) Copyright 2005-2021 hSenid Software International (Pvt) Limited.
 * All Rights Reserved.
 * <p/>
 * These materials are unpublished, proprietary, confidential source code of
 * hSenid Software International (Pvt) Limited and constitute a TRADE SECRET
 * of hSenid Software International (Pvt) Limited.
 * <p/>
 * hSenid Software International (Pvt) Limited retains all title to and intellectual
 * property rights in these materials.
 */

@Configuration
@EnableWebSecurity
public class SecurityConfiguration {
    @Value("${keycloak-redirect-uri.success-url}")
    private String successUrl;

    @Autowired
    private CustomAuthenticationEvents authenticationEventsPublisher;

    @Autowired
    private KeycloakUtil keycloakUtil;

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {

        http.csrf(AbstractHttpConfigurer::disable)
                .headers(headers -> headers
                        .addHeaderWriter(new XFrameOptionsHeaderWriter(XFrameOptionsHeaderWriter.XFrameOptionsMode.DENY)))
                .oauth2Login(oauth2Login -> oauth2Login
                        .tokenEndpoint(tokenEndpoint -> {
                        })
                        .userInfoEndpoint(userInfoEndpoint ->
                                userInfoEndpoint.userAuthoritiesMapper(
                                        authenticationConverter(realmRolesAuthoritiesConverter())
                                )
                        )
                        .successHandler(new SimpleUrlAuthenticationSuccessHandler(successUrl))
                ).sessionManagement(session -> session
                        .sessionCreationPolicy(SessionCreationPolicy.ALWAYS)
                );

        http.authorizeHttpRequests(authorize -> authorize
                .requestMatchers("/actuator", "/actuator/**").permitAll()
                .requestMatchers("/oauth2/**", "/login/**").permitAll()
                .anyRequest().authenticated());

        http.logout(logout -> logout
                .logoutUrl("/logout")
                .logoutSuccessHandler((
                        request,
                        response,
                        authentication
                ) -> {
                    String keycloakLogoutUrl = keycloakUtil.buildKeycloakLogoutUrl(authentication);
                    response.sendRedirect(keycloakLogoutUrl);
                })
                .invalidateHttpSession(true)
                .clearAuthentication(true)
                .permitAll()
        );
        return http.build();
    }

    @Bean
    @SuppressWarnings("unchecked")
    AuthoritiesConverter realmRolesAuthoritiesConverter() {
        return claims -> {
            var realmAccess = Optional.ofNullable((Map<String, Object>) claims.get("realm_access"));
            var roles = realmAccess.flatMap(map ->
                    Optional.ofNullable((List<String>) map.get("roles"))
            );

            return roles.orElse(Collections.emptyList()).stream()
                    .map(role -> new SimpleGrantedAuthority("ROLE_" + role.toUpperCase()))
                    .map(GrantedAuthority.class::cast)
                    .collect(Collectors.toList());
        };
    }

    @Bean
    public GrantedAuthoritiesMapper authenticationConverter(
            Converter<Map<String, Object>, Collection<GrantedAuthority>> authoritiesConverter) {
        return (authorities) -> authorities.stream()
                .filter(authority -> authority instanceof OidcUserAuthority)
                .map(OidcUserAuthority.class::cast)
                .flatMap(oidcAuth -> {
                    // Merge roles from ID token and UserInfo (Keycloak may place roles in either)
                    Map<String, Object> idTokenClaims = oidcAuth.getIdToken() != null ? oidcAuth.getIdToken().getClaims() : Collections.emptyMap();
                    Map<String, Object> userInfoClaims = oidcAuth.getUserInfo() != null ? oidcAuth.getUserInfo().getClaims() : Collections.emptyMap();

                    Collection<GrantedAuthority> fromIdToken = Optional.ofNullable(authoritiesConverter.convert(idTokenClaims))
                            .orElse(Collections.emptyList());
                    Collection<GrantedAuthority> fromUserInfo = Optional.ofNullable(authoritiesConverter.convert(userInfoClaims))
                            .orElse(Collections.emptyList());

                    return Arrays.asList(fromIdToken, fromUserInfo).stream().flatMap(Collection::stream);
                })
                .collect(Collectors.toSet());
    }
}

