package hms.core.m1.rsc.rscservice.cache.repository.Impl

import com.fasterxml.jackson.databind.ObjectMapper
import com.fasterxml.jackson.module.kotlin.readValue
import hms.core.m1.rsc.rscservice.cache.CachedData
import hms.core.m1.rsc.rscservice.cache.repository.CacheRepository
import org.slf4j.LoggerFactory
import org.springframework.dao.EmptyResultDataAccessException
import org.springframework.jdbc.core.JdbcTemplate
import org.springframework.jdbc.core.RowMapper
import org.springframework.stereotype.Repository

/**
 * JDBC implementation of CacheRepository using MariaDB
 * 
 * Provides ACID transactions for cache operations and handles
 * JSON serialization for complex types (Msisdns list).
 */
@Repository
class CacheRepositoryImpl(
    private val jdbcTemplate: JdbcTemplate,
    private val objectMapper: ObjectMapper
) : CacheRepository {

    companion object {
        @JvmStatic
        private val LOGGER = LoggerFactory.getLogger(CacheRepositoryImpl::class.java)
    }

    private val cachedDataRowMapper = RowMapper<CachedData> { rs, _ ->
        CachedData(
            roamingStatus = rs.getBoolean("roaming_status"),
            multiSim = rs.getObject("multi_sim") as Boolean?,
            memberMsisdns = parseMemberMsisdns(rs.getString("member_msisdns")),
            vlrAddress = rs.getString("vlr_address") ?: ""
        )
    }

    private val cacheEntryRowMapper = RowMapper<Pair<String, CachedData>> { rs, _ ->
        val msisdn = rs.getString("id")
        val data = CachedData(
            roamingStatus = rs.getBoolean("roaming_status"),
            multiSim = rs.getObject("multi_sim") as Boolean?,
            memberMsisdns = parseMemberMsisdns(rs.getString("member_msisdns")),
            vlrAddress = rs.getString("vlr_address") ?: ""
        )
        msisdn to data
    }

    override fun get(msisdn: String): CachedData? {
        return try {
            jdbcTemplate.queryForObject(
                """
                SELECT roaming_status, multi_sim, member_msisdns, vlr_address
                FROM cached_data_table
                WHERE id = ? AND expires_at > NOW()
                """,
                cachedDataRowMapper,
                msisdn
            )
        } catch (e: EmptyResultDataAccessException) {
            LOGGER.debug("Returned empty cache entry for msisdn[$msisdn]")
            null
        }
    }

    override fun upsert(msisdn: String, data: CachedData, ttlMinutes: Long) {
        val memberMsisdnsJson = objectMapper.writeValueAsString(data.memberMsisdns)

        val rowsAffected = jdbcTemplate.update(
            """
            INSERT INTO cached_data_table 
            (id, roaming_status, multi_sim, member_msisdns, vlr_address, expires_at)
            VALUES (?, ?, ?, ?, ?, NOW() + INTERVAL ? MINUTE)
            ON DUPLICATE KEY UPDATE
                roaming_status = VALUES(roaming_status),
                multi_sim = VALUES(multi_sim),
                member_msisdns = VALUES(member_msisdns),
                vlr_address = VALUES(vlr_address),
                expires_at = VALUES(expires_at),
                updated_at = CURRENT_TIMESTAMP
            """,
            msisdn,
            data.roamingStatus,
            data.multiSim,
            memberMsisdnsJson,
            data.vlrAddress,
            ttlMinutes
        )

        LOGGER.debug("Upserted cache entry for [$msisdn], rows affected: [$rowsAffected]")
    }

    override fun delete(msisdn: String): CachedData? {
        // Retrieve before delete
        val cachedData = get(msisdn)

        if (cachedData != null) {
            val rowsDeleted = jdbcTemplate.update(
                "DELETE FROM cached_data_table WHERE id = ?",
                msisdn
            )
            LOGGER.debug("Deleted cache entry for [$msisdn], rows deleted: [$rowsDeleted]")
        }

        return cachedData
    }

    override fun deleteAll(): Int {
        val rowsDeleted = jdbcTemplate.update("DELETE FROM cached_data_table")
        LOGGER.debug("Deleted all cache entries, rows deleted: [$rowsDeleted]")
        return rowsDeleted
    }

    override fun getAllActive(): List<Pair<String, CachedData>> {
        val result =  jdbcTemplate.query(
            """
            SELECT id, roaming_status, multi_sim, member_msisdns, vlr_address
            FROM cached_data_table
            WHERE expires_at > NOW()
            ORDER BY updated_at DESC
            """,
            cacheEntryRowMapper
        )

        LOGGER.debug("Returned all active cache entries, rows: [${result.size}]")

        return result
    }

    override fun cleanupExpired(): Int {
        val rowsDeleted = jdbcTemplate.update(
            "DELETE FROM cached_data_table WHERE expires_at <= NOW()"
        )

        if (rowsDeleted > 0) {
            LOGGER.debug("Deleted expired cache entries, rows deleted: [$rowsDeleted]")
        }

        return rowsDeleted
    }

    override fun count(): Int {
        return jdbcTemplate.queryForObject(
            "SELECT COUNT(*) FROM cached_data_table WHERE expires_at > NOW()",
            Int::class.java
        ) ?: 0
    }

    /**
     * Parse JSON array string to List<String>
     * Handles null and empty cases gracefully
     */
    private fun parseMemberMsisdns(json: String?): List<String> {
        if (json.isNullOrBlank()) return emptyList()

        return try {
            objectMapper.readValue<List<String>>(json)
        } catch (e: Exception) {
            LOGGER.error("Failed to parse member_msisdns JSON: [$json]", e)
            emptyList()
        }
    }
}

package hms.core.m1.rsc.rscservice.cache.scheduler

import com.github.benmanes.caffeine.cache.Cache
import hms.core.m1.rsc.rscservice.cache.CachedData
import hms.core.m1.rsc.rscservice.cache.repository.CacheRepository
import io.micrometer.core.instrument.MeterRegistry
import org.slf4j.LoggerFactory
import org.springframework.beans.factory.annotation.Value
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty
import org.springframework.scheduling.annotation.Scheduled
import org.springframework.stereotype.Component
import java.util.concurrent.TimeUnit

/**
 * Scheduler to synchronize L1 (Caffeine) cache from L2 (MariaDB)
 * 
 * Runs periodically to ensure eventual consistency across all instances:
 * - Fetches all active cache entries from MariaDB
 * - Updates local Caffeine cache with fresh data
 * - Provides up to 2-minute consistency guarantee (configurable via fixed rate)
 * 
 * This scheduler is the primary mechanism for cross-instance cache coherence
 * in the hybrid cache architecture.
 */
@Component
@ConditionalOnProperty(
    prefix = "cache.sync.scheduler",
    name = ["enabled"],
    havingValue = "true",
    matchIfMissing = true
)
class CacheSyncScheduler(
    private val cacheRepository: CacheRepository,
    private val caffeineCache: Cache<String, CachedData>,
    private val meterRegistry: MeterRegistry,
    @Value("\${spring.application.name}") private val nodeId: String
) {

    companion object {
        @JvmStatic
        private val LOGGER = LoggerFactory.getLogger(CacheSyncScheduler::class.java)
    }

    /**
     * Sync L1 cache from L2 database
     * 
     * Default: runs every 2 minutes (120000ms) with 30s initial delay
     * Can be configured via cache.sync.scheduler.fixed-rate-ms
     */
    @Scheduled(
        fixedRateString = "\${cache.sync.scheduler.fixed-rate-ms:120000}",
        initialDelayString = "\${cache.sync.scheduler.initial-delay-ms:30000}"
    )
    fun syncCacheFromDatabase() {
        val startTime = System.currentTimeMillis()

        try {
            LOGGER.debug("Starting cache sync from L2 cache")

            // Fetch all active entries from MariaDB
            val allEntries = cacheRepository.getAllActive()

            // Get current L1 cache keys for comparison
            val currentL1Keys = HashSet(caffeineCache.asMap().keys)
            val l2Keys = allEntries.map { it.first }.toSet()

            // Update L1 cache
            var updatedCount = 0
            var newCount = 0
            var unchangedCount = 0
            var deletedCount = 0

            allEntries.forEach { (msisdn, data) ->
                val existingData = caffeineCache.getIfPresent(msisdn)

                when {
                    existingData == null -> {
                        // New entry - add to cache
                        caffeineCache.put(msisdn, data)
                        newCount++
                    }
                    existingData != data -> {
                        // Data changed - update cache
                        caffeineCache.put(msisdn, data)
                        updatedCount++
                    }
                    else -> {
                        // Data unchanged - skip update
                        unchangedCount++
                    }
                }
            }

            // Remove entries from L1 that don't exist in L2 (deleted entries)
            val keysToDelete: Set<String> = currentL1Keys - l2Keys
            keysToDelete.forEach { msisdn: String ->
                caffeineCache.invalidate(msisdn)
                deletedCount++
            }

            val duration = System.currentTimeMillis() - startTime

            LOGGER.info(
                "Cache sync completed: total=[${allEntries.size}], new=[$newCount], " +
                "updated=[$updatedCount], unchanged=[$unchangedCount], deleted=[$deletedCount], duration=[${duration}ms]"
            )

            // Record metrics
            meterRegistry.counter("cache.sync.success", "node", nodeId).increment()
            meterRegistry.timer("cache.sync.duration", "node", nodeId).record(duration, TimeUnit.MILLISECONDS)
            meterRegistry.gauge("cache.sync.entries.total", listOf(), allEntries.size)
            meterRegistry.gauge("cache.sync.entries.new", listOf(), newCount)
            meterRegistry.gauge("cache.sync.entries.updated", listOf(), updatedCount)
            meterRegistry.gauge("cache.sync.entries.unchanged", listOf(), unchangedCount)
            meterRegistry.gauge("cache.sync.entries.deleted", listOf(), deletedCount)

        } catch (e: Exception) {
            LOGGER.error("Cache sync failed", e)
            meterRegistry.counter("cache.sync.failure", "node", nodeId).increment()
        }
    }

    /**
     * Get current cache statistics for monitoring
     */
    fun getCacheStats(): Map<String, Any> {
        val stats = caffeineCache.stats()
        return mapOf(
            "hitCount" to stats.hitCount(),
            "missCount" to stats.missCount(),
            "hitRate" to stats.hitRate(),
            "evictionCount" to stats.evictionCount(),
            "estimatedSize" to caffeineCache.estimatedSize()
        )
    }
}

package hms.core.m1.rsc.rscservice.cache.scheduler

import hms.core.m1.rsc.rscservice.cache.repository.CacheRepository
import io.micrometer.core.instrument.MeterRegistry
import org.slf4j.LoggerFactory
import org.springframework.beans.factory.annotation.Value
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty
import org.springframework.scheduling.annotation.Scheduled
import org.springframework.stereotype.Component

/**
 * Scheduler to clean up expired cache entries from MariaDB
 * 
 * Runs periodically to remove entries where expires_at <= NOW():
 * - Prevents unlimited database growth
 * - Maintains cache table performance
 * - Complements TTL enforcement (Caffeine handles L1 expiration automatically)
 * 
 * Default: runs every 5 minutes (300000ms)
 */
@Component
@ConditionalOnProperty(
    prefix = "cache.cleanup.scheduler",
    name = ["enabled"],
    havingValue = "true",
    matchIfMissing = true
)
class CacheCleanupScheduler(
    private val cacheRepository: CacheRepository,
    private val meterRegistry: MeterRegistry,
    @Value("\${spring.application.name}") private val nodeId: String
) {

    companion object {
        @JvmStatic
        private val LOGGER = LoggerFactory.getLogger(CacheCleanupScheduler::class.java)
    }

    /**
     * Clean up expired cache entries from database
     * 
     * Default: runs every 5 minutes (300000ms)
     * Can be configured via cache.cleanup.scheduler.fixed-rate-ms
     */
    @Scheduled(
        fixedRateString = "\${cache.cleanup.scheduler.fixed-rate-ms:300000}"
    )
    fun cleanupExpiredCache() {
        try {
            val deletedCount = cacheRepository.cleanupExpired()

            if (deletedCount > 0) {
                LOGGER.info("Cleaned up [$deletedCount] expired cache entries")
            } else {
                LOGGER.debug("No expired entries to clean up")
            }

            // Record metrics
            meterRegistry.counter(
                "cache.cleanup.entries",
                "status", "deleted",
                "node", nodeId
            ).increment(deletedCount.toDouble())

            meterRegistry.counter(
                "cache.cleanup.success",
                "node", nodeId
            ).increment()

        } catch (e: Exception) {
            LOGGER.error("Cache cleanup failed, node: [$nodeId]", e)
            meterRegistry.counter(
                "cache.cleanup.failure",
                "node", nodeId
            ).increment()
        }
    }
}

package hms.core.m1.rsc.rscservice.cache.config

import com.github.benmanes.caffeine.cache.Cache
import com.github.benmanes.caffeine.cache.Caffeine
import hms.core.m1.rsc.rscservice.cache.CachedData
import org.slf4j.LoggerFactory
import org.springframework.beans.factory.annotation.Value
import org.springframework.context.annotation.Bean
import org.springframework.context.annotation.Configuration
import org.springframework.scheduling.annotation.EnableScheduling
import java.util.concurrent.TimeUnit

/**
 * Configuration for Caffeine L1 cache and scheduling components
 * 
 * Caffeine provides high-performance in-memory caching with:
 * - Size-based eviction (LFU algorithm)
 * - Time-based expiration
 * - Statistics recording for monitoring
 */
@Configuration
@EnableScheduling
class CacheConfiguration {

    companion object {
        @JvmStatic
        private val LOGGER = LoggerFactory.getLogger(CacheConfiguration::class.java)
    }

    /**
     * Create Caffeine cache bean for L1 (in-memory) cache layer
     * 
     * Configuration:
     * - maximumSize: 100 entries per instance (matches Hazelcast config)
     * - expireAfterWrite: 240 minutes (max TTL for non-neighboring MSISDNs)
     * - recordStats: Enable metrics collection
     * 
     * @param maxSize Maximum number of entries in L1 cache
     * @param ttlMinutes TTL for cache entries (will be overridden by DB TTL on sync)
     */
    @Bean
    fun caffeineCache(
        @Value("\${cache.caffeine.max-size:100}") maxSize: Long,
        @Value("\${cache.caffeine.ttl-duration:240}") ttlDuration: Long,
        @Value("\${cache.caffeine.ttl-unit:MINUTES}") ttlUnit: TimeUnit
    ): Cache<String, CachedData> {
        LOGGER.info("Initializing Caffeine L1 cache with maxSize=[$maxSize], ttl=[$ttlDuration] $ttlUnit")

        return Caffeine.newBuilder()
            .maximumSize(maxSize)
            .expireAfterWrite(ttlDuration, ttlUnit)
            .recordStats()
            .removalListener<String, CachedData> { key, _, cause ->
                LOGGER.debug("L1 cache eviction: key=[{}], cause=[{}]", key, cause)
            }
            .build()
    }
}

