package hms.core.m1.rsc.dataloader.service.lock

import kotlinx.coroutines.runBlocking
import org.slf4j.LoggerFactory
import org.springframework.beans.factory.annotation.Value
import org.springframework.jdbc.datasource.DataSourceUtils
import org.springframework.stereotype.Component
import java.sql.Connection
import java.util.concurrent.ConcurrentHashMap
import javax.sql.DataSource

@Component
class DistributedTemplateLockManager(
    private val dataSource: DataSource,
    @Value("\${lock.node-id}") private val nodeId: String,
    @Value("\${lock.acquire-timeout-millis}") private val lockAcquireTimeoutMilliSeconds: Long
) {
    companion object {
        private val LOGGER = LoggerFactory.getLogger(DistributedTemplateLockManager::class.java)
    }

    private val activeLockConnections = ConcurrentHashMap<String, Connection>()

    fun runWithLocking(lock_id: String, scheduler: String, fn: () -> Unit) {
        val lockId = "$scheduler-$lock_id"
        LOGGER.info("Trying to acquire lock for template id: [$lock_id] for scheduler: [$scheduler]")
        val start = System.currentTimeMillis()
        val timeoutSeconds = convertTimeout(lockAcquireTimeoutMilliSeconds)
        if (!isLockAcquired(lockId, timeoutSeconds)) {
            LOGGER.debug(
                "Lock acquisition failed for lock: [$lockId] duration: [${System.currentTimeMillis() - start}]"
            )
            return
        }

        try {
            LOGGER.info("LOCKED: [$lockId]")
            runBlocking {
                fn()
            }
        } catch (th: Throwable) {
            LOGGER.error("Error occurred during locked section for lock [$lockId]", th)
            throw th
        } finally {
            releaseLock(lockId, start)
        }
    }

    private fun isLockAcquired(lockId: String, timeoutSeconds: Double): Boolean {
        val connection = DataSourceUtils.getConnection(dataSource)
        connection.autoCommit = true
        return try {
            var acquired = false
            connection.prepareStatement("SELECT GET_LOCK(?, ?)").use { ps ->
                ps.setString(1, lockId)
                ps.setDouble(2, timeoutSeconds)
                ps.executeQuery().use { rs ->
                    acquired = rs.takeIf { it.next() }?.getInt(1) == 1
                }
            }
            if (acquired) {
                activeLockConnections[lockId] = connection
                true
            } else {
                releaseConnection(connection)
                false
            }
        } catch (ex: Exception) {
            LOGGER.error("Failed to acquire database lock [$lockId]", ex)
            releaseConnection(connection)
            false
        }
    }

    private fun releaseLock(lockId: String, start: Long) {
        val connection = activeLockConnections.remove(lockId)
        if (connection == null) {
            LOGGER.debug("No active connection for lock [$lockId]")
            return
        }

        try {
            connection.prepareStatement("SELECT RELEASE_LOCK(?)").use { ps ->
                ps.setString(1, lockId)
                ps.executeQuery().use { rs ->
                    if (rs.next()) {
                        when (rs.getInt(1)) {
                            1 -> LOGGER.info(
                                "UNLOCKED: [$lockId] duration: [${System.currentTimeMillis() - start}]"
                            )
                            0 -> LOGGER.info("Release lock reported no lock held for [$lockId]")
                            else -> LOGGER.info("Release lock returned unexpected value for [$lockId]")
                        }
                    } else {
                        LOGGER.warn("Release lock query returned no result for [$lockId]")
                    }
                }
            }
        } catch (ex: Exception) {
            LOGGER.error("Failed to release database lock [$lockId]", ex)
        } finally {
            releaseConnection(connection)
        }
    }

    private fun releaseConnection(connection: Connection) {
        DataSourceUtils.releaseConnection(connection, dataSource)
    }

    private fun convertTimeout(milliseconds: Long) = milliseconds.toDouble() / 1000.0
}

