package hms.core.m1.rsc.rscservice.auth.credentials

import jakarta.xml.bind.DatatypeConverter
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Component
import java.security.MessageDigest

interface PasswordService {
    fun encode(password: String): ByteArray
    fun validatePassword(visitorPassword: String, encodedPassword: String): Boolean
    fun encodeToHexBinaryString(byteArray: ByteArray): String
}

@Component
class DefaultPasswordService: PasswordService {

    companion object {
        @JvmStatic
        private val LOGGER = LoggerFactory.getLogger(DefaultPasswordService::class.java)
    }

    override fun encode(password: String): ByteArray {
        val messageDigest = MessageDigest.getInstance("MD5")
        messageDigest.update(password.toByteArray())
        return messageDigest.digest()
    }

    override fun encodeToHexBinaryString(byteArray: ByteArray): String {
        return DatatypeConverter.printHexBinary(byteArray)
    }

    override fun validatePassword(visitorPassword: String, encodedPassword: String): Boolean {
        LOGGER.debug("Validating password")
        if (visitorPassword.isEmpty() || encodedPassword.isEmpty()) {
            LOGGER.debug("Passwords cannot be empty")
            return false
        }
        val encodePassword = encode(visitorPassword)
        val visitorPasswordBinaryString = encodeToHexBinaryString(encodePassword)
        return visitorPasswordBinaryString == encodedPassword
    }

}

