package hms.core.m1.rsc.rscservice.validator

import hms.core.m1.rsc.rscservice.error.CommonError
import hms.core.m1.rsc.rscservice.error.NotAcceptableException
import hms.core.m1.rsc.rscservice.logs.EventLogger
import hms.core.m1.rsc.rscservice.workflow.*
import org.slf4j.LoggerFactory
import org.springframework.beans.factory.annotation.Value
import org.springframework.boot.logging.LoggerGroup
import org.springframework.stereotype.Component

@Component
class NumberRangeValidator(
    @Value("\${service-api.msisdn-validations.range}") private val numberRangeRegex: List<String>,
    private val eventLogger: EventLogger
) : AbstractWorkFlowStep("NumberRange", eventLogger) {
    companion object {
        @JvmStatic
        private val LOGGER = LoggerFactory.getLogger(NumberRangeValidator::class.java)
    }


    override suspend fun doProcess(context: Context): WorkFlowStepResult {
        if (LOGGER.isTraceEnabled) {
            LOGGER.trace("Doing number range validation for [$context]")
        }
        val range: Boolean = numberRangeRegex.map { Regex(it) }.any { prefix ->
            prefix.matches(context.msisdn)
        }
        return if (range) {
            LOGGER.info("Number range validation success [${context.msisdn}]")
            WorkflowStepSuccess()
        } else {
            LOGGER.info("Number range validation failed, returning roaming false [${context.msisdn}]")
            context.roamingStatus = false
            WorkflowStepSuccess()
        }
    }
}

