import hms.core.m1.rsc.rscservice.workflow.*
import org.slf4j.LoggerFactory
import org.springframework.beans.factory.annotation.Value
import org.springframework.stereotype.Component

@Component
class NumberLengthValidator(
    @Value("\${service-api.msisdn-validations.length}") private val numberLength: Int,
    private val eventLogger: EventLogger
) : AbstractWorkFlowStep("NumberLength", eventLogger) {
    companion object {
        @JvmStatic
        private val LOGGER = LoggerFactory.getLogger(NumberLengthValidator::class.java)
    }

    override suspend fun doProcess(context: Context): WorkFlowStepResult {
        if (LOGGER.isTraceEnabled) {
            LOGGER.trace("Doing number length validation for [$context]")
        }
        return if (context.msisdn.length != numberLength) {
            LOGGER.info("Number length validation failed, returning roaming false [${context.msisdn}]")
            context.roamingStatus = false
            WorkflowStepSuccess()
        } else {
            LOGGER.info("Number length validation success [${context.msisdn}]")
            WorkflowStepSuccess()
        }

    }
}

package hms.core.m1.rsc.rscservice.validator

import hms.core.m1.rsc.rscservice.connectors.CallType
import hms.core.m1.rsc.rscservice.connectors.SpmlConnectorAdapter
import hms.core.m1.rsc.rscservice.error.CommonError
import hms.core.m1.rsc.rscservice.error.DefaultErrorException
import hms.core.m1.rsc.rscservice.error.InternalErrorException
import hms.core.m1.rsc.rscservice.error.NotAcceptableException
import hms.core.m1.rsc.rscservice.logs.EventLogger
import hms.core.m1.rsc.rscservice.workflow.*
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Component

@Component
class SpmlExistsValidator(val spmlConnectorAdapter: SpmlConnectorAdapter, private val eventLogger: EventLogger) : AbstractWorkFlowStep("ExistInHLR", eventLogger) {

    companion object {
        @JvmStatic
        private val LOGGER = LoggerFactory.getLogger(SpmlExistsValidator::class.java)
    }

    override suspend fun doProcess(context: Context): WorkFlowStepResult {
        return try {
            val spmlData = spmlConnectorAdapter.getSpmlData(context.msisdn, CallType.SEARCH_REQUEST)
            if (spmlData != null) {
                context.vlrAddress = spmlData.isdnNumberOfVLR
                context.odboc = spmlData.odboc
                context.multiSim = spmlData.isMultiSim
                WorkflowStepSuccess()
            } else {
                LOGGER.info("MSISDN not found in HLR returning roaming false [{}]", context.msisdn)
                context.roamingStatus = false
                WorkflowStepSuccess()
            }
        } catch (e: DefaultErrorException) {
            LOGGER.error("Error occurred while processing number exists in HLR [{}]", context.msisdn, e)
            WorkflowStepFailure(e)
        } catch (e: Exception) {
            LOGGER.error("Error occurred while processing number exists in HLR [{}]", context.msisdn, e)
            WorkflowStepFailure(InternalErrorException(CommonError("Error occurred while processing number exists in HLR [${context.msisdn}]")))
        }
    }
}
